from __future__ import annotations

import argparse
import json
import os
import re
import urllib.request
from pathlib import Path
from typing import Any

DEFAULT_ENDPOINT = os.environ.get(
    "HERMCLAW_LITELLM_URL",
    "http://127.0.0.1:4000/v1/chat/completions",
)
DEFAULT_MODEL = os.environ.get(
    "HERMCLAW_HEAVY_ALIAS",
    "local-coder-qwen38-24k",
)
DEFAULT_OLLAMA_URL = os.environ.get(
    "HERMCLAW_HEAVY_OLLAMA_URL",
    "http://192.168.178.224:11434",
).rstrip("/")
DEFAULT_OLLAMA_MODEL = os.environ.get(
    "HERMCLAW_HEAVY_OLLAMA_MODEL",
    "qwen3.8:27b",
)


def _extract_json(text: str) -> dict[str, Any]:
    cleaned = text.strip()
    fence = chr(96) * 3
    if cleaned.startswith(fence):
        cleaned = re.sub(
            r"^" + re.escape(fence) + r"(?:json)?\s*",
            "",
            cleaned,
            flags=re.IGNORECASE,
        )
        cleaned = re.sub(
            r"\s*" + re.escape(fence) + r"$",
            "",
            cleaned,
        )
    try:
        return json.loads(cleaned)
    except json.JSONDecodeError:
        start = cleaned.find("{")
        end = cleaned.rfind("}")
        if start >= 0 and end > start:
            return json.loads(cleaned[start:end + 1])
        raise


def _fail_closed(
    reason: str,
    verifier: dict[str, Any],
) -> dict[str, Any]:
    return {
        "schema": 1,
        "verdict": "corrections",
        "summary": (
            "Heavy Review konnte keinen belastbaren "
            "Abschluss erzeugen."
        ),
        "issues": [
            {
                "severity": "blocker",
                "path": "",
                "evidence": reason,
                "required_change": (
                    "Heavy Review erneut ausführen. "
                    "Deterministische Blocker dürfen "
                    "unabhängig davon nicht als PASS gelten."
                ),
            }
        ],
        "tests_to_run": [],
        "verifier_ok": bool(verifier.get("ok")),
        "_generated_by": "fail_closed",
    }


def _validate_review(
    review: dict[str, Any],
    verifier: dict[str, Any],
    *,
    source: str = "heavy_model_validated",
) -> dict[str, Any]:
    verdict = str(
        review.get("verdict", "")
    ).strip().lower()
    if verdict not in {"pass", "corrections"}:
        raise ValueError(
            "verdict muss 'pass' oder 'corrections' sein."
        )

    issues = review.get("issues")
    if not isinstance(issues, list):
        raise ValueError("issues muss eine Liste sein.")

    tests_to_run = review.get(
        "tests_to_run",
        [],
    )
    if not isinstance(tests_to_run, list):
        raise ValueError(
            "tests_to_run muss eine Liste sein."
        )

    normalized = {
        "schema": 1,
        "verdict": verdict,
        "summary": str(
            review.get("summary", "")
        ).strip(),
        "issues": issues,
        "tests_to_run": tests_to_run,
        "verifier_ok": bool(
            verifier.get("ok")
        ),
        "_generated_by": source,
    }

    if not verifier.get("ok") and verdict == "pass":
        normalized["verdict"] = "corrections"
        normalized["issues"] = [
            {
                "severity": "blocker",
                "path": "",
                "evidence": (
                    "Deterministischer Verifier enthält "
                    "Blocker; Heavy PASS wird fail-closed "
                    "überschrieben."
                ),
                "required_change": (
                    "Alle deterministischen Blocker beheben "
                    "und danach erneut prüfen."
                ),
            },
            *issues,
        ]
    return normalized


def build_prompt(
    handoff: dict[str, Any],
    verifier: dict[str, Any],
    diff: str,
) -> str:
    diff = diff[-60000:]
    return f"""Du bist der unabhängige Heavy Reviewer einer autonomen Coding-Pipeline.
Du hast KEINE Tools. Bewerte ausschließlich das Handoff, den deterministischen
Verifier-Report und den tatsächlichen Git-Diff.

ZIEL:
Ein PASS ist nur erlaubt, wenn die Implementierung fachlich korrekt, sicher und
durch die vorhandenen Belege plausibel verifiziert ist.

Prüfe insbesondere:
- Stimmen Änderungen mit task/requested_changes/constraints überein?
- Wird Benutzereingabe serverseitig normalisiert und nicht nur im HTML begrenzt?
- Wird derselbe normalisierte Wert bis Backend/DB und zurück ins UI konsistent verwendet?
- Sind Empty-State/Filterzustände logisch korrekt?
- Sind SQL-/PDO-Parameter bei nativen Prepares korrekt und eindeutig?
- Entstehen TypeErrors durch unerwartete Request-Typen (Array statt String etc.)?
- Gibt es Security-/Berechtigungs-/Status-Regressionen?
- Wurden fachfremde Dateien geändert?
- Reichen die ausgeführten Checks aus oder fehlt ein konkreter Test?

HANDOFF:
{json.dumps(handoff, ensure_ascii=False, indent=2)}

DETERMINISTISCHER VERIFIER:
{json.dumps(verifier, ensure_ascii=False, indent=2)}

GIT-DIFF:
{diff}

Antworte ausschließlich als valides JSON ohne Markdown:
{{
  "verdict": "pass" oder "corrections",
  "summary": "kurze belastbare Gesamtbewertung",
  "issues": [
    {{
      "severity": "blocker|major|minor",
      "path": "Dateipfad oder leer",
      "evidence": "konkreter Beleg aus Diff/Verifier",
      "required_change": "präzise notwendige Korrektur"
    }}
  ],
  "tests_to_run": ["konkreter zusätzlicher Test, falls nötig"]
}}
"""


def _request_message(
    *,
    endpoint: str,
    model: str,
    prompt: str,
    timeout: int,
    recovery: bool,
) -> dict[str, Any]:
    user_prompt = prompt
    max_tokens = 2200
    if recovery:
        user_prompt = (
            prompt
            + "\n\nRECOVERY-AUFRUF:\n"
            + (
                "Der vorherige Aufruf lieferte kein "
                "verwertbares finales JSON. "
            )
            + (
                "Gib JETZT nur das finale JSON-Objekt aus. "
                "Keine Analyse, kein Markdown, keine Vorrede. "
                "/no_think"
            )
        )
        max_tokens = 1600

    payload = {
        "model": model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "Du bist ein strenger unabhängiger "
                    "Code-Reviewer. Kein PASS bei unbelegten "
                    "Annahmen oder offenen Blockern. "
                    "Die sichtbare Antwort muss ein einzelnes "
                    "JSON-Objekt sein."
                ),
            },
            {
                "role": "user",
                "content": user_prompt,
            },
        ],
        "temperature": 0,
        "max_tokens": max_tokens,
        "response_format": {
            "type": "json_object",
        },
    }

    request = urllib.request.Request(
        endpoint,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json"
        },
        method="POST",
    )
    with urllib.request.urlopen(
        request,
        timeout=timeout,
    ) as response:
        raw = json.loads(
            response.read().decode("utf-8")
        )
    return raw["choices"][0]["message"]


def _request_ollama_json(
    *,
    ollama_url: str,
    ollama_model: str,
    prompt: str,
    timeout: int,
) -> dict[str, Any]:
    payload = {
        "model": ollama_model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "Du bist ein strenger unabhängiger "
                    "Code-Reviewer. Antworte ausschließlich "
                    "als valides JSON-Objekt."
                ),
            },
            {
                "role": "user",
                "content": (
                    prompt
                    + "\n\nDIREKTER JSON-FALLBACK: "
                    + "Gib jetzt ausschließlich das finale "
                    + "JSON-Objekt aus. Keine Analyse, kein Markdown."
                ),
            },
        ],
        "stream": False,
        "think": False,
        "format": "json",
        "keep_alive": "5m",
        "options": {
            "temperature": 0,
            "num_ctx": 24576,
            "num_predict": 1800,
        },
    }
    request = urllib.request.Request(
        ollama_url.rstrip("/") + "/api/chat",
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json"
        },
        method="POST",
    )
    with urllib.request.urlopen(
        request,
        timeout=timeout,
    ) as response:
        raw = json.loads(
            response.read().decode("utf-8")
        )
    message = raw.get("message") or {}
    if not isinstance(message, dict):
        raise ValueError(
            "Ollama-Antwort enthält kein message-Objekt."
        )
    return message


def _parse_message(
    message: dict[str, Any],
    verifier: dict[str, Any],
    *,
    source: str,
) -> dict[str, Any]:
    content = str(
        message.get("content") or ""
    ).strip()
    if not content:
        reasoning = str(
            message.get("reasoning_content") or ""
        )
        raise ValueError(
            f"Leerer content; reasoning_chars={len(reasoning)}"
        )
    parsed = _extract_json(content)
    return _validate_review(
        parsed,
        verifier,
        source=source,
    )


def review(
    handoff: dict[str, Any],
    verifier: dict[str, Any],
    diff: str,
    endpoint: str,
    model: str,
    timeout: int = 600,
    ollama_url: str = DEFAULT_OLLAMA_URL,
    ollama_model: str = DEFAULT_OLLAMA_MODEL,
) -> dict[str, Any]:
    prompt = build_prompt(
        handoff,
        verifier,
        diff,
    )
    first_error = ""

    try:
        first = _request_message(
            endpoint=endpoint,
            model=model,
            prompt=prompt,
            timeout=timeout,
            recovery=False,
        )
        return _parse_message(
            first,
            verifier,
            source="heavy_model_validated",
        )
    except Exception as exc:
        first_error = (
            f"{type(exc).__name__}: {exc}"
        )

    try:
        second = _request_message(
            endpoint=endpoint,
            model=model,
            prompt=prompt,
            timeout=timeout,
            recovery=True,
        )
        result = _parse_message(
            second,
            verifier,
            source="heavy_model_recovered",
        )
        result["_recovery_reason"] = first_error
        return result
    except Exception as exc:
        second_error = (
            f"{type(exc).__name__}: {exc}"
        )

    try:
        direct = _request_ollama_json(
            ollama_url=ollama_url,
            ollama_model=ollama_model,
            prompt=prompt,
            timeout=timeout,
        )
        result = _parse_message(
            direct,
            verifier,
            source="heavy_ollama_recovered",
        )
        result["_recovery_reason"] = (
            f"LiteLLM Erstaufruf: {first_error}; "
            f"LiteLLM Recovery: {second_error}"
        )
        return result
    except Exception as exc:
        direct_error = (
            f"{type(exc).__name__}: {exc}"
        )
        return _fail_closed(
            (
                f"LiteLLM Erstaufruf: {first_error}; "
                f"LiteLLM Recovery: {second_error}; "
                f"direktes Ollama: {direct_error}"
            ),
            verifier,
        )


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Heavy Review nach deterministischer "
            "Verifikation"
        )
    )
    parser.add_argument(
        "--handoff",
        required=True,
    )
    parser.add_argument(
        "--verifier",
        required=True,
    )
    parser.add_argument(
        "--diff",
        required=True,
    )
    parser.add_argument(
        "--output",
        required=True,
    )
    parser.add_argument(
        "--endpoint",
        default=DEFAULT_ENDPOINT,
    )
    parser.add_argument(
        "--model",
        default=DEFAULT_MODEL,
    )
    parser.add_argument(
        "--timeout",
        type=int,
        default=600,
    )
    parser.add_argument(
        "--ollama-url",
        default=DEFAULT_OLLAMA_URL,
    )
    parser.add_argument(
        "--ollama-model",
        default=DEFAULT_OLLAMA_MODEL,
    )
    args = parser.parse_args()

    handoff = json.loads(
        Path(args.handoff).read_text(
            encoding="utf-8"
        )
    )
    verifier = json.loads(
        Path(args.verifier).read_text(
            encoding="utf-8"
        )
    )
    diff = Path(args.diff).read_text(
        encoding="utf-8",
        errors="replace",
    )

    result = review(
        handoff,
        verifier,
        diff,
        args.endpoint,
        args.model,
        args.timeout,
        args.ollama_url,
        args.ollama_model,
    )
    Path(args.output).write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    print(
        f"[HEAVY] verdict: {result['verdict']}"
    )
    print(
        "[HEAVY] issues: "
        f"{len(result.get('issues', []))}"
    )
    print(
        "[HEAVY] source: "
        f"{result.get('_generated_by')}"
    )
    if result.get("_recovery_reason"):
        print(
            "[HEAVY] Recovery nach erstem "
            "ungültigem Output: "
            f"{result['_recovery_reason']}"
        )
    print(
        f"[HEAVY] Report: {args.output}"
    )
    return (
        0
        if result["verdict"] == "pass"
        else 30
    )


if __name__ == "__main__":
    raise SystemExit(main())

import json
import unittest
from unittest.mock import patch

from model_runtime.heavy_review import (
    _validate_review,
    review,
)


class HeavyReviewTests(unittest.TestCase):
    def test_pass_is_overridden_when_verifier_failed(self):
        model_review = {
            "verdict": "pass",
            "summary": "ok",
            "issues": [],
            "tests_to_run": [],
        }
        result = _validate_review(
            model_review,
            {"ok": False},
        )
        self.assertEqual(
            result["verdict"],
            "corrections",
        )
        self.assertTrue(result["issues"])

    def test_pass_kept_when_verifier_ok(self):
        model_review = {
            "verdict": "pass",
            "summary": "ok",
            "issues": [],
            "tests_to_run": [],
        }
        result = _validate_review(
            model_review,
            {"ok": True},
        )
        self.assertEqual(
            result["verdict"],
            "pass",
        )

    @patch(
        "model_runtime.heavy_review._request_ollama_json"
    )
    @patch(
        "model_runtime.heavy_review._request_message"
    )
    def test_reasoning_only_first_call_recovers(
        self,
        request_message,
        request_ollama,
    ):
        request_message.side_effect = [
            {
                "content": "",
                "reasoning_content": (
                    "lange interne Analyse"
                ),
            },
            {
                "content": json.dumps(
                    {
                        "verdict": "corrections",
                        "summary": (
                            "PDO-Blocker beheben"
                        ),
                        "issues": [
                            {
                                "severity": "blocker",
                                "path": (
                                    "inc/funktionen_benutzer.php"
                                ),
                                "evidence": (
                                    "duplicate placeholder"
                                ),
                                "required_change": (
                                    "eindeutige Placeholder"
                                ),
                            }
                        ],
                        "tests_to_run": [
                            "PHP Syntax"
                        ],
                    }
                )
            },
        ]

        result = review(
            {},
            {
                "ok": False,
                "blockers": [
                    {"code": "X"}
                ],
            },
            "diff",
            "http://example.invalid",
            "model",
            1,
        )

        self.assertEqual(
            result["verdict"],
            "corrections",
        )
        self.assertEqual(
            result["_generated_by"],
            "heavy_model_recovered",
        )
        self.assertIn(
            "Leerer content",
            result["_recovery_reason"],
        )
        self.assertEqual(
            request_message.call_count,
            2,
        )
        request_ollama.assert_not_called()

    @patch(
        "model_runtime.heavy_review._request_ollama_json"
    )
    @patch(
        "model_runtime.heavy_review._request_message"
    )
    def test_direct_ollama_is_third_fallback(
        self,
        request_message,
        request_ollama,
    ):
        request_message.side_effect = [
            {
                "content": "",
                "reasoning_content": "r1",
            },
            {
                "content": "",
                "reasoning_content": "r2",
            },
        ]
        request_ollama.return_value = {
            "content": json.dumps(
                {
                    "verdict": "pass",
                    "summary": "ok",
                    "issues": [],
                    "tests_to_run": [],
                }
            )
        }

        result = review(
            {},
            {"ok": True},
            "diff",
            "http://example.invalid",
            "model",
            1,
            "http://ollama.invalid",
            "qwen",
        )

        self.assertEqual(
            result["verdict"],
            "pass",
        )
        self.assertEqual(
            result["_generated_by"],
            "heavy_ollama_recovered",
        )
        self.assertEqual(
            request_message.call_count,
            2,
        )
        request_ollama.assert_called_once()


if __name__ == "__main__":
    unittest.main()
